create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,email text not null,product_id text not null default 'redwood',product_name text not null default 'RedWood',version text not null default 'v1.0.0',amount_total integer not null default 5990,currency text not null default 'eur',stripe_session_id text unique not null,stripe_payment_intent_id text,purchased_at timestamptz not null default now());alter table public.purchases enable row level security;drop policy if exists "Users can read their purchases" on public.purchases;create policy "Users can read their purchases" on public.purchases for select to authenticated using(auth.uid()=user_id);create index if not exists purchases_user_id_idx on public.purchases(user_id);